package com.yuegang.zhihui.training.application;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.training.api.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
public final class TrainingLearningRecordService{private final JdbcTemplate jdbc;private final ObjectMapper json;public TrainingLearningRecordService(DataSource dataSource,ObjectMapper json){jdbc=new JdbcTemplate(dataSource);this.json=json;}public void recordPosition(long user,ReadingPositionRequest request){long assignment=positive(request.assignmentId()),chapter=positive(request.chapterId());Integer owned=jdbc.queryForObject("SELECT COUNT(*) FROM training_assignment a JOIN training_chapter c ON c.course_id=a.course_id WHERE a.id=? AND a.user_id=? AND c.id=? AND a.status IN('ASSIGNED','IN_PROGRESS')",Integer.class,assignment,user,chapter);if(owned==null||owned!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);jdbc.update("INSERT INTO training_chapter_progress(assignment_id,chapter_id,last_position,last_nonce) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE last_position=IF(last_nonce<>VALUES(last_nonce) OR last_nonce IS NULL,VALUES(last_position),last_position),last_nonce=VALUES(last_nonce),version=version+1",assignment,chapter,request.position(),request.nonce());}public List<ChapterProgressView>progress(long user,String assignmentId){long assignment=positive(assignmentId);Integer owned=jdbc.queryForObject("SELECT COUNT(*) FROM training_assignment WHERE id=? AND user_id=?",Integer.class,assignment,user);if(owned==null||owned!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return jdbc.query("SELECT chapter_id,active_seconds,last_position,completed,completed_at,version FROM training_chapter_progress WHERE assignment_id=? ORDER BY chapter_id",(r,n)->new ChapterProgressView(Long.toString(r.getLong(1)),r.getInt(2),r.getString(3),r.getBoolean(4),r.getTimestamp(5)==null?null:r.getTimestamp(5).toLocalDateTime().atOffset(ZoneOffset.UTC),r.getLong(6)),assignment);}public List<QuizAttemptDetailView>attempts(long user,String assignmentId){long assignment=positive(assignmentId);return jdbc.query("SELECT id,assignment_id,gate_id,score,passed,answers_json,submitted_at FROM training_quiz_attempt WHERE assignment_id=? AND user_id=? ORDER BY submitted_at DESC",(r,n)->new QuizAttemptDetailView(Long.toString(r.getLong(1)),Long.toString(r.getLong(2)),Long.toString(r.getLong(3)),r.getInt(4),r.getBoolean(5),read(r.getString(6)),r.getTimestamp(7).toLocalDateTime().atOffset(ZoneOffset.UTC)),assignment,user);}public TrainingAnalyticsView analytics(){var totals=jdbc.query("SELECT COUNT(*),SUM(status='COMPLETED'),SUM(status<>'COMPLETED' AND due_at<NOW(6)) FROM training_assignment",r->{r.next();return new long[]{r.getLong(1),r.getLong(2),r.getLong(3)};});BigDecimal average=Optional.ofNullable(jdbc.queryForObject("SELECT AVG(score) FROM training_quiz_attempt",BigDecimal.class)).orElse(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);var weak=jdbc.query("SELECT knowledge_code,SUM(wrong_count) total FROM training_weakness GROUP BY knowledge_code ORDER BY total DESC LIMIT 20",(r,n)->new TrainingAnalyticsView.WeakKnowledgeView(r.getString(1),r.getLong(2)));BigDecimal rate=totals[0]==0?BigDecimal.ZERO:BigDecimal.valueOf(totals[1]*100).divide(BigDecimal.valueOf(totals[0]),2,RoundingMode.HALF_UP);return new TrainingAnalyticsView(totals[0],totals[1],totals[2],rate,average,weak);}private Map<String,String>read(String value){try{return json.readValue(value,new TypeReference<>(){});}catch(Exception e){return Map.of();}}private static long positive(String value){try{long id=Long.parseLong(value);if(id<=0)throw new NumberFormatException();return id;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
